SQL_STMT_U.val:
SELECT x.SlipDate, x.SlipNo, x.ProductName, x.Quantity, x.UnitName, x.UnitPrice, x.UnitPriceTotal, x.TaxMark, CASE WHEN x.ProductName = '前回残高' THEN :4 ELSE @balance := @balance + COALESCE(x.UnitPriceTotal, 0) END AS RunningBalance FROM ( /* ① 仕入明細 */ SELECT i.slip_date AS SlipDate, id.incoming_delivery_id AS SlipNo, CONVERT(p.name USING utf8mb4) COLLATE utf8mb4_general_ci AS ProductName, CAST(id.quantity AS DECIMAL(20,4)) AS Quantity, CONVERT(u.name USING utf8mb4) COLLATE utf8mb4_general_ci AS UnitName, CAST(id.unit_price AS DECIMAL(20,2)) AS UnitPrice, CAST(id.quantity * id.unit_price AS DECIMAL(20,2)) AS UnitPriceTotal, CONVERT( CASE WHEN p.tax_rate_type = 2 THEN '＊' ELSE '' END USING utf8mb4 ) COLLATE utf8mb4_general_ci AS TaxMark, id.slip_row AS LineNo FROM incoming_delivery_detail id INNER JOIN incoming_delivery i ON i.id = id.incoming_delivery_id LEFT JOIN unit u ON u.id = id.unit_id LEFT JOIN product p ON p.product_cd = id.product_cd WHERE i.supplier_id = :1 AND i.slip_date BETWEEN ':2' AND ':3'
UNION ALL
/* ② 消費税（仕入伝票単位） */ SELECT i.slip_date AS SlipDate, i.id AS SlipNo, CONVERT('消費税' USING utf8mb4) COLLATE utf8mb4_general_ci AS ProductName, NULL AS Quantity, CONVERT(NULL USING utf8mb4) COLLATE utf8mb4_general_ci AS UnitName, NULL AS UnitPrice, CAST( COALESCE(i.reduced_tax, 0) + COALESCE(i.standard_tax, 0) AS DECIMAL(20,2) ) AS UnitPriceTotal, CONVERT('' USING utf8mb4) COLLATE utf8mb4_general_ci AS TaxMark, 9999 AS LineNo FROM incoming_delivery i INNER JOIN supplier s ON s.id = i.supplier_id WHERE i.supplier_id = :1 AND i.slip_date BETWEEN ':2' AND ':3' AND s.tax_category <> 2 AND (COALESCE(i.reduced_tax, 0) + COALESCE(i.standard_tax, 0)) <> 0
UNION ALL
/* ③ 支払データ */ SELECT d.payment_date AS SlipDate, d.id AS SlipNo, CONVERT('[ 支 払 ]' USING utf8mb4) COLLATE utf8mb4_general_ci AS ProductName, NULL AS Quantity, CONVERT(NULL USING utf8mb4) COLLATE utf8mb4_general_ci AS UnitName, NULL AS UnitPrice, CAST( -(COALESCE(d.amount, 0) + COALESCE(d.fee, 0)) AS DECIMAL(20,2) ) AS UnitPriceTotal, CONVERT('' USING utf8mb4) COLLATE utf8mb4_general_ci AS TaxMark, 99999 AS LineNo FROM disbursement d WHERE d.payment_destination_id = :1 AND d.payment_date BETWEEN ':2' AND ':3'
UNION ALL
/* ④ 前回残高 */ SELECT DATE_SUB(':2', INTERVAL 1 DAY) AS SlipDate, NULL AS SlipNo, CONVERT('前回残高' USING utf8mb4) COLLATE utf8mb4_general_ci AS ProductName, NULL AS Quantity, CONVERT(NULL USING utf8mb4) COLLATE utf8mb4_general_ci AS UnitName, NULL AS UnitPrice, NULL AS UnitPriceTotal, CONVERT('' USING utf8mb4) COLLATE utf8mb4_general_ci AS TaxMark, 0 AS LineNo
UNION ALL
/* ⑤ 消費税調整（月末に1行） */ SELECT LAST_DAY(':2') AS SlipDate, NULL AS SlipNo, CONVERT('消費税調整' USING utf8mb4) COLLATE utf8mb4_general_ci AS ProductName, NULL AS Quantity, CONVERT(NULL USING utf8mb4) COLLATE utf8mb4_general_ci AS UnitName, NULL AS UnitPrice, CAST(SUM(pf.tax_adjustment) AS DECIMAL(20,2)) AS UnitPriceTotal, CONVERT('' USING utf8mb4) COLLATE utf8mb4_general_ci AS TaxMark, 999999 AS LineNo FROM payables_file pf WHERE pf.supplier_id = :1 AND pf.year_month BETWEEN ':2' AND ':3' HAVING SUM(pf.tax_adjustment) IS NOT NULL AND SUM(pf.tax_adjustment) <> 0
) AS x JOIN (SELECT @balance := :4) AS init WHERE :1 <> 0 AND ( :4 <> 0 OR EXISTS ( SELECT 1 FROM incoming_delivery i WHERE i.supplier_id = :1 AND i.slip_date BETWEEN ':2' AND ':3' UNION SELECT 1 FROM disbursement d WHERE d.payment_destination_id = :1 AND d.payment_date BETWEEN ':2' AND ':3' ) ) ORDER BY x.SlipDate, x.LineNo, x.SlipNo;
